def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            version_part, _ = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease_part = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # A version with pre-release sorts before one without
        # So we return a tuple where: (has_prerelease, identifier_comparison_key)
        if identifiers is None:
            # No pre-release: sorts after any pre-release
            return (1, ())
        else:
            # Has pre-release: sorts before no pre-release
            # Convert each identifier to a comparable form
            key_parts = []
            for identifier in identifiers:
                if identifier.isdigit():
                    # All-digit identifiers sort before non-digit ones
                    # Use (0, numeric_value) so digits come first
                    key_parts.append((0, int(identifier)))
                else:
                    # Non-digit identifiers compare by ASCII order
                    # Use (1, string_value) so they come after digits
                    key_parts.append((1, identifier))
            return (0, tuple(key_parts))

    def sort_key(item):
        index, version_string = item
        major, minor, patch, prerelease_identifiers = parse_version(version_string)
        return (major, minor, patch, prerelease_key(prerelease_identifiers), index)

    # Add original indices to maintain stability for equal versions
    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, v in sorted_versions]

